{"command": "cd /tmp && python3 << 'EOF'
from PIL import Image, ImageOps
orig = Image.open('/app/radiograph.jpg'); flat = Image.open('/tmp/flat.png')
crops = {
 'L1': (1270, 790, 1390, 930),
 'L2': (1380, 780, 1500, 930),
}
for name,(x1,y1,x2,y2) in crops.items():
    for tag,src in (('o',orig),('f',flat)):
        c = src.crop((x1,y1,x2,y2))
        c = c.resize((c.width*6, c.height*6), Image.LANCZOS)
        ImageOps.autocontrast(c, cutoff=1).save(f'/tmp/{name}_{tag}.png')
print('ok')
EOF", "description": "6x zoom of the two dark ovals in lower left premolar region"}

